    faq: [{ q: "Do eggs cause high cholesterol?", a: "For many people, the overall pattern and saturated fat intake matter more than one food. Your lab response, portions, and other health risks should guide the decision." }, { q: "Can diet replace a statin?", a: "Sometimes lifestyle change is enough for a person's risk level; sometimes medication is strongly recommended. That decision should be based on your overall cardiovascular risk with your clinician." }],
    image: "generated/heart-health-foods.png",
    imageAlt: "Fiber-rich and unsaturated-fat foods for cholesterol care",
    sources: [sources.cholesterol, sources.heart],
